#include "core.h"

// GND-SIN: generated by tools/make_engine.py. The sound is in voices/gnd_sin.hpp.
namespace mmsin {
inline void initialize(Voice& voice, Shared& shared, u32 owner) { md::gnd_sin::reset(voice.state, shared.common, owner); }
inline void start(Voice& voice, Shared& shared, u32) { md::gnd_sin::trigger(voice.state, shared.common); }
inline void destroy(Voice&, Shared&, u32) {}
inline void render(Voice& voice, Shared& shared, u32, opxy::Output output, opxy::Parameters parameters, opxy::Pitch pitch) {
    // The machine's eight slots from the definition's 4 (definition.json).
    i32 own[8] = {};
    own[7] = parameters[3];
    md::gnd_sin::render(voice.state, shared.common, output, own, pitch);
}
}
